'use strict'

const convict = require('convict')
const json = require('json5')
const toml = require('@iarna/toml')
const yaml = require('js-yaml')

const PRIMITIVE_TYPES = [Boolean, Number, String]
const COERCE_SCHEMA = yaml.FAILSAFE_SCHEMA
const YAML_SCHEMA = yaml.CORE_SCHEMA.withTags(yaml.mergeTag)
const YAML_PREFIX_RX = new RegExp('!!((?:auto|str|bool|int|float|seq|map)(?= )|null(?=$))(?: |$)')

const parseYaml = (source) => yaml.load(source || null, { schema: YAML_SCHEMA })

/**
 * A convict function wrapper that registers custom formats and parsers and
 * isolates the configuration from the process environment by default.
 */
function solitaryConvict (schema, opts) {
  registerFormats(convict)
  registerParsers(convict)
  return convict(schema, opts || { args: [], env: {} })
}

function registerParsers (convict) {
  convict.addParser([
    { extension: 'json', parse: json.parse },
    { extension: 'toml', parse: toml.parse },
    { extension: 'yaml', parse: parseYaml },
    { extension: 'yml', parse: parseYaml },
    {
      extension: '*',
      parse: () => {
        throw new Error('Unknown playbook file extension: must be .yml (or .yaml), .json, or .toml')
      },
    },
  ])
}

function registerFormats (convict) {
  convict.addFormat({
    name: 'array',
    validate: (val) => {
      if (!(val == null || Array.isArray(val))) throw new Error('must be an array or null')
    },
  })
  convict.addFormat({
    name: 'string',
    validate: (val) => {
      if (!(val == null || val.constructor === String)) throw new Error('must be a string or null')
    },
  })
  convict.addFormat({
    name: 'array-or-string',
    validate: (val) => {
      if (!(val == null || val.constructor === String || Array.isArray(val))) {
        throw new Error('must be an array, string, or null')
      }
    },
  })
  convict.addFormat({
    name: 'boolean-or-array-or-string',
    validate: (val) => {
      if (!(val == null || typeof val === 'boolean' || val.constructor === String || Array.isArray(val))) {
        throw new Error('must be a boolean, array, string, or null')
      }
    },
  })
  convict.addFormat({
    name: 'map',
    validate: (val) => {
      if (!(val == null || val.constructor === Object)) throw new Error('must be a map (i.e., key/value pairs)')
    },
    coerce: (val, config, name) => {
      if (config == null) return val
      const accum = config.get(name) ?? config.default(name) ?? {}
      const entries = yaml.load(val, { schema: COERCE_SCHEMA })
      for (const entry of Array.isArray(entries) ? entries : [entries]) {
        let k = entry
        let v = ''
        const equalsIdx = entry.indexOf('=')
        if (~equalsIdx) {
          if (!(k = entry.substring(0, equalsIdx))) continue
          v = entry.substring(equalsIdx + 1)
        }
        let parsed = v
        if (v) {
          const match = v.match(YAML_PREFIX_RX)
          if (match) {
            try {
              parsed = yaml.load(match[1] === 'auto' ? v.substring(7) : v, { schema: yaml.CORE_SCHEMA })
            } catch {}
          }
        }
        accum[k] = parsed
      }
      return accum
    },
  })
  convict.addFormat({
    name: 'primitive-map',
    validate: (val) => {
      if (val == null) return
      if (
        !(
          val.constructor === Object &&
          Object.entries(val).every(([k, v]) => k && (!v || ~PRIMITIVE_TYPES.indexOf(v.constructor)))
        )
      ) {
        throw new Error('must be a primitive map (i.e., key/value pairs, primitive values only)')
      }
    },
    coerce: (val, config, name) => {
      if (config == null) return val
      const accum = config.get(name) ?? config.default(name) ?? {}
      const entries = yaml.load(val, { schema: COERCE_SCHEMA })
      for (const entry of Array.isArray(entries) ? entries : [entries]) {
        let k = entry
        let v = ''
        const equalsIdx = entry.indexOf('=')
        if (~equalsIdx) {
          if (!(k = entry.substring(0, equalsIdx))) continue
          v = entry.substring(equalsIdx + 1)
        }
        let parsed = v
        if (v) {
          const match = v.match(YAML_PREFIX_RX)
          if (match) {
            try {
              parsed = yaml.load(match[1] === 'auto' ? v.substring(7) || null : v, { schema: yaml.CORE_SCHEMA })
              if (parsed && !~PRIMITIVE_TYPES.indexOf(parsed.constructor)) parsed = v
            } catch {}
          }
        }
        accum[~k.indexOf('-') ? k.replace(/-/g, '_') : k] = parsed
      }
      return accum
    },
  })
  convict.addFormat({
    name: 'require-array',
    validate: (val) => {
      if (!(val == null || Array.isArray(val))) throw new Error('must be an array or null')
    },
    coerce: (val, config, name) => {
      if (config == null) return val
      const accum = config.get(name) ?? config.default(name) ?? []
      const byId = {}
      const byRequire = {}
      let orderIdx = 0
      const order = new Map()
      for (const [idx, it] of accum.entries()) {
        const ext = it.constructor === Object ? it : (accum[idx] = { require: it })
        byRequire[ext.require] ??= ext
        if ('id' in ext) byId[ext.id] ??= ext
        order.set(it, orderIdx++)
      }
      for (let request of val.split(',')) {
        const enable = request.charAt() === '!' ? (request = request.substring(1)) == null : true
        let match
        if ((match = byId[request] ?? byRequire[request])) {
          if ((match.enabled ?? true) !== enable) match.enabled = enable
        } else {
          accum.push((match = byRequire[request] = { require: request }))
          if (!enable) match.enabled = false
        }
        if ((match.order ?? 'auto') === 'auto') order.set(match, orderIdx++)
      }
      return accum
        .sort((a, b) => order.get(a) - order.get(b))
        .map((it) => (Object.keys(it).length === 1 && 'require' in it ? it.require : it))
    },
  })
  convict.addFormat({
    name: 'boolean-or-string',
    validate: (val) => {
      if (!(val == null || val.constructor === String || val.constructor === Boolean)) {
        throw new Error('must be a boolean, string, or null')
      }
    },
  })
  convict.addFormat({
    name: 'dir-or-virtual-files',
    validate: (val) => {
      if (!(val == null || val.constructor === String || Array.isArray(val))) {
        throw new Error('must be a directory path, list of virtual files, or null')
      }
    },
  })
  convict.addFormat({
    name: 'url',
    validate: (val) => {
      if (val == null) return
      if (val.constructor !== String) throw new Error('must be a string or null')
      let protocol
      try {
        protocol = new URL(val).protocol
      } catch {
        throw new Error('must be a valid URL')
      }
      if (!(protocol === 'https:' || protocol === 'http:')) throw new Error('must be an HTTP or HTTPS URL')
    },
  })
  convict.addFormat({
    name: 'url-or-pathname',
    validate: (val) => {
      if (val == null) return
      if (val.constructor !== String) throw new Error('must be a string or null')
      let parsedUrl
      try {
        parsedUrl = new URL((val.charAt() === '/' ? 'https://example.org' : '') + val)
      } catch {
        throw new Error('must be a valid URL or a pathname (i.e., root-relative path)')
      }
      if (parsedUrl.protocol !== 'https:' && parsedUrl.protocol !== 'http:') {
        throw new Error('must be an HTTP or HTTPS URL or a pathname (i.e., root-relative path)')
      }
      if (~parsedUrl.pathname.indexOf('%20')) throw new Error('pathname segment must not contain spaces')
    },
    coerce: (val) => {
      if (!val || val === '~') return null
      return val.length > 1 && val.charAt(val.length - 1) === '/' ? val.substring(0, val.length - 1) : val
    },
  })
}

module.exports = solitaryConvict
